      {"text": "Одно изменение давления Δp для всех точек элемента.", "claims": ["c4"], "hypothesis": false},
      {"text": "Коэффициенты объёмной упругости жидкости β_ж и пласта β_с.", "claims": [], "hypothesis": true}
    ],
    "outputs": [
      {"text": "ΔV_ж — изменение объёма жидкости в элементе.", "claims": ["c6"], "hypothesis": false},
      {"text": "ΔV_п — изменение объёма пор в элементе.", "claims": ["c7"], "hypothesis": false},
      {"text": "ΔV_з — изменение упругого запаса элемента.", "claims": ["c4"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Если Δp различно в разных точках элемента, одной величиной Δp не обойтись.", "claims": ["c4"], "hypothesis": true},
      {"text": "Без соглашения о знаке Δp данные по жидкости и порам могут выглядеть противоречивыми.", "claims": ["c6", "c7"], "hypothesis": false},
      {"text": "Если коэффициенты получены не при начальном давлении, отсчёт V0ж может дать ошибку.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
